///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDFIL05106";
scwin.stockExerTbody = null;
scwin.resultShrs = undefined;
scwin.nowDate = "";
scwin.exerShrs = undefined;
scwin.stockDutyarr = undefined;
scwin.stockDutyExerarr = undefined;

///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — param.follwBzProcsNo, param.bzProcsNo, param.listProcsStatCd

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "addRow", fn: function(){ return ((String(((dma_pageContext.get("follwBzProcsNo") ?? "")) == null ? '' : ((dma_pageContext.get("follwBzProcsNo") ?? ""))).length === 0) && (String(((dma_pageContext.get("bzProcsNo") ?? "")) == null ? '' : ((dma_pageContext.get("bzProcsNo") ?? ""))).length === 0) && (String(((dma_pageContext.get("listProcsStatCd") ?? "")) == null ? '' : ((dma_pageContext.get("listProcsStatCd") ?? ""))).length === 0)); } }, { id: "btn_delete", fn: function(){ return (! (String(((dma_pageContext.get("listProcsStatCd") ?? "")) == null ? '' : ((dma_pageContext.get("listProcsStatCd") ?? ""))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_bzProcsNo", fn: function () { return String((dma_pageContext.get("bzProcsNo") ?? "")); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

