t.getCellData(i, "stkoptDutyExerStartDd") ?? (() => { throw new Error("unresolved:" + "stockDutyList[__i].stkoptDutyExerStartDd"); })())) == null ? '' : ((dlt_stockDutyList.getCellData(i, "stkoptDutyExerStartDd") ?? (() => { throw new Error("unresolved:" + "stockDutyList[__i].stkoptDutyExerStartDd"); })()))).indexOf('$' + '{') >= 0 ? '' : String(((dlt_stockDutyList.getCellData(i, "stkoptDutyExerStartDd") ?? (() => { throw new Error("unresolved:" + "stockDutyList[__i].stkoptDutyExerStartDd"); })())) == null ? '' : ((dlt_stockDutyList.getCellData(i, "stkoptDutyExerStartDd") ?? (() => { throw new Error("unresolved:" + "stockDutyList[__i].stkoptDutyExerStartDd"); })())))), stkoptDutyExerEndDd: (String(((dlt_stockDutyList.getCellData(i, "stkoptDutyExerEndDd") ?? (() => { throw new Error("unresolved:" + "stockDutyList[__i].stkoptDutyExerEndDd"); })())) == null ? '' : ((dlt_stockDutyList.getCellData(i, "stkoptDutyExerEndDd") ?? (() => { throw new Error("unresolved:" + "stockDutyList[__i].stkoptDutyExerEndDd"); })()))).indexOf('$' + '{') >= 0 ? '' : String(((dlt_stockDutyList.getCellData(i, "stkoptDutyExerEndDd") ?? (() => { throw new Error("unresolved:" + "stockDutyList[__i].stkoptDutyExerEndDd"); })())) == null ? '' : ((dlt_stockDutyList.getCellData(i, "stkoptDutyExerEndDd") ?? (() => { throw new Error("unresolved:" + "stockDutyList[__i].stkoptDutyExerEndDd"); })())))), prtdepoEndDd: (String(((dlt_stockDutyList.getCellData(i, "prtdepoEndDd") ?? (() => { throw new Error("unresolved:" + "stockDutyList[__i].prtdepoEndDd"); })())) == null ? '' : ((dlt_stockDutyList.getCellData(i, "prtdepoEndDd") ?? (() => { throw new Error("unresolved:" + "stockDutyList[__i].prtdepoEndDd"); })()))).indexOf('$' + '{') >= 0 ? '' : String(((dlt_stockDutyList.getCellData(i, "prtdepoEndDd") ?? (() => { throw new Error("unresolved:" + "stockDutyList[__i].prtdepoEndDd"); })())) == null ? '' : ((dlt_stockDutyList.getCellData(i, "prtdepoEndDd") ?? (() => { throw new Error("unresolved:" + "stockDutyLis