/**
 * @method
 * @name onload
 * @description onload 처리
 * @returns {void}
 * @hidden N
 */
scwin.onload = function () {
    try {
        form = (document.stockDutyExerForm || { elements: [] });
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldfil05106.onload" });
    }
};

/**
 * @method
 * @name grd_stockDutyList_2_oncellclick
 * @description grd_stockDutyList_2 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {void}
 * @hidden N
 */
scwin.grd_stockDutyList_2_oncellclick = function (rowIndex, columnIndex, columnId) {
    try { if (columnId === '_del') { const d = $c.util.getComponent('dlt_stockDutyList'); if (d && d.removeRow) { d.removeRow(rowIndex); }  return; }
    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05106.grd_stockDutyList_2_oncellclick' }); }
};

