 */
scwin.grd_stockDutyList_2_oneditend = function (rowIndex, columnIndex, value) {  };

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_register
 * @description register 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_register = async function (action) {
    const sbmOptions = {
        id: "tx_fn_register",
        method: "post",
        action: action ?? "/list/stockDutyExerPopup.do",
        ref: "dma_registerReq",
        target: "dlt_stockDutyList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_delete
 * @description delete 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_delete = async function (action) {
    const sbmOptions = {
        id: "tx_fn_delete",
        method: "post",
        action: action ?? "/list/stockDutyExerPopup.do",
        ref: "dma_deleteReq",
        target: "dlt_stockDutyList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_load_list
 * @description load list 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/list/stockDutyExerPopup.do?method=selectStockDutyExer&isurCd=",
        ref: "dma_loadListReq",
        target: "dlt_stockDutyList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name selectStockDutyExer
 * @description select Stock Duty Exer 처리
 * @param {*} ipt_bzProcsNo ipt_bzProcsNo
 * @param {String} ipt_prtdepoId ipt_prtdepoId
 * @returns {void}
 * @hidden N
 */
scwin.selectStockDutyExer = function (ipt_bzProcsNo, ipt_prtdepoId) {
    let addHtml = "";
    scwin.exerShrs = 0;
    scwin.stockExerTbody.setLabel("");
    for (let i = 0; i < scwin.stockDutyExerarr.length; i++) {
        if (ipt_bzProcsNo === scwin.stockDutyExerarr[i].bzProcsNo && ipt_prtdepoId === scwin.stockDutyExerarr[i].prtdepoId && scwin.stockDutyExerarr[i].stkoptDutyExerPayDd !== "") {
            addHtml += '<tr><td class="td_board" align="right">' + scwin.dateFormat(scwin.stockDutyExerarr[i].stkoptDutyExerPayDd) + '</td>' + '<td class="td_board" align="right">' + $c.num.formatNumber(scwin.stockDutyExerarr[i].stkoptDutyExerShrs) + '</td>' + '<td class="td_board" align="right"></td></tr>';
            scwin.exerShrs += parseInt(scwin.stockDutyExerarr[i].stkoptDutyExerShrs);
        }
    }
    if (addHtml === "") {
        addHtml += '<tr><td colspan="4" class="td_board_2" >조회내용이 없습니다.</td></tr>';
    }
    $("#stockExerTbody").append(addHtml);
};

/**
 * @method
 * @name validate
 * @description validate 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.validate = async function () {
    let inserShrs = 0;
    for (let i = 0; i < $("input[name=stkoptDutyExerShrs]").length; i++) {
        inserShrs += parseInt($("input[name=stkoptDutyExerShrs]").eq(i).val());
    }
    if (parseInt(scwin.exerShrs) + parseInt(inserShrs) > parseInt(scwin.resultShrs)) {
        await $c.win.alert("총 부여주식수보다 행사주식수의 합이 많습니다.");
        return false;
    }
    let ddCnt = 0;
    /* 수동 전환 필요: 이름 선택자 순회 [name=stkoptDutyExerPayDd] — B4 반복 밖 동명 입력(정적/계수 틀) · to-be 에 돌 요소가 없다 */ $("input[name=cal_stkoptDutyExerPayDd]").each(async function(index, item) {
            if ($(item).val() === "") {
                await $c.win.alert("납입일을 입력해 하세요.");
                ddCnt++;
                return false;
            }
    });
    if (ddCnt !== 0) {
        return false;
    }
    let shrsCnt = 0;
    /* 수동 전환 필요: 이름 선택자 순회 [name=stkoptDutyExerShrs] — B4 반복 밖 동명 입력(정적/계수 틀) · to-be 에 돌 요소가 없다 */ $("input[name=stkoptDutyExerShrs]").each(async function(index, item) {
            if ($(item).val() === "") {
                await $c.win.alert("행사주식수를 입력해 하세요.");
                shrsCnt++;
                return false;
            }
    });
    if (shrsCnt !== 0) {
        return false;
    }
    return true;
};

/**
 * @method
 * @name register
 * @description register 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.register = async function () {
    const opener = scwin.openerScwin();
    if (await scwin.validate()) {
        if ($c.util.getComponent('dma_registerReq').get('listProcsStatCd') === "") {
            (document.stockDutyExerForm || { elements: [] }).target = 'stockDutyExerWin';
            $c.util.getComponent('dma_registerReq').set('method', "insertStockDutyExer");
            await scwin.tx_fn_register("stockDutyExerPopup.do");
        } else {
            (document.stockDutyExerForm || { elements: [] }).target = 'stockDutyExerWin';
            $c.util.getComponent('dma_registerReq').set('method', "updateStockDutyExer");
            await scwin.tx_fn_register("stockDutyExerPopup.do");
        }
    }
};

/**
 * @method
 * @name deleteRegisterReq
 * @description delete Register Req 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.deleteRegisterReq = async function () {
    const opener = scwin.openerScwin();
    (document.stockDutyExerForm || { elements: [] }).target = 'stockDutyExerWin';
    $c.util.getComponent('dma_registerReq').set('method', "deleteStockDutyExer");
    await scwin.tx_fn_delete("stockDutyExerPopup.do");
    opener.calcelYn = 'N';
};

/**
 * @method
 * @name cancel
 * @description cancel 처리
 * @returns {void}
 * @hidden N
 */
scwin.cancel = function () {
    const opener = scwin.openerScwin();
    opener.calcelYn = 'Y';
    $c.win.closePopup();
};

/**
 * @method
 * @name close
 * @description close 처리
 * @returns {void}
 * @hidden N
 */
scwin.close = function () {
    const opener = scwin.openerScwin();
    opener.calcelYn = 'N';
    $c.win.closePopup();
};

/**
 * @method
 * @name selectChange
 * @description select Change 처리
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.selectChange = async function (e) {
    const index = $("select[name=prtdepoIdSelect]").val();
    (console.error('[sdd] 이 화면 문서에 #txt_stkoptDutyHdInputTpNm 가 없다 — html() 무동작(as-is 는 공용 템플릿·소거된 요소를 잡았다)'), $("#txt_stkoptDutyHdInputTpNm")).html(scwin.stockDutyarr[index].stkoptDutyHdInputTpNm);
    (console.error('[sdd] 이 화면 문서에 #txt_prtdepoPrnTpNm 가 없다 — html() 무동작(as-is 는 공용 템플릿·소거된 요소를 잡았다)'), $("#txt_prtdepoPrnTpNm")).html(scwin.stockDutyarr[index].prtdepoPrnTpNm);
    (console.error('[sdd] #nm html() 무동작 — 그리드 «열 정의»에는 DOM 이 없다'), $("#nm")).html(scwin.stockDutyarr[index].nm);
    (console.error('[sdd] 이 화면 문서에 #txt_encrypResdbzRegNo 가 없다 — html() 무동작(as-is 는 공용 템플릿·소거된 요소를 잡았다)'), $("#txt_encrypResdbzRegNo")).html(scwin.stockDutyarr[index].encrypResdbzRegNo);
    (console.error('[sdd] 이 화면 문서에 #txt_stkoptDutyResolDd 가 없다 — html() 무동작(as-is 는 공용 템플릿·소거된 요소를 잡았다)'), $("#txt_stkoptDutyResolDd")).html(scwin.dateFormat(scwin.stockDutyarr[index].stkoptDutyResolDd));
    (console.error('[sdd] 이 화면 문서에 #txt_stkoptDutyTotGrntShrs 가 없다 — html() 무동작(as-is 는 공용 템플릿·소거된 요소를 잡았다)'), $("#txt_stkoptDutyTotGrntShrs")).html($c.num.formatNumber(scwin.stockDutyarr[index].stkoptDutyTotGrntShrs) + "주");
    (console.error('[sdd] 이 화면 문서에 #txt_prtdepoObjKindNm 가 없다 — html() 무동작(as-is 는 공용 템플릿·소거된 요소를 잡았다)'), $("#txt_prtdepoObjKindNm")).html(scwin.stockDutyarr[index].prtdepoObjKindNm);
    (console.error('[sdd] 이 화면 문서에 #txt_stkoptDutyExerStartDd 가 없다 — html() 무동작(as-is 는 공용 템플릿·소거된 요소를 잡았다)'), $("#txt_stkoptDutyExerStartDd")).html(scwin.dateFormat(scwin.stockDutyarr[index].stkoptDutyExerStartDd) + "~" + scwin.dateFormat(scwin.stockDutyarr[index].stkoptDutyExerEndDd));
    (console.error('[sdd] 이 화면 문서에 #txt_prtdepoEndDd 가 없다 — html() 무동작(as-is 는 공용 템플릿·소거된 요소를 잡았다)'), $("#txt_prtdepoEndDd")).html(scwin.dateFormat(scwin.stockDutyarr[index].prtdepoEndDd));
    $c.util.getComponent('ipt_bzProcsNo').setValue(scwin.stockDutyarr[index].bzProcsNo);
    $c.util.getComponent('ipt_prtdepoId').setValue(scwin.stockDutyarr[index].prtdepoId);
    scwin.selectStockDutyExer(scwin.stockDutyarr[index].bzProcsNo, scwin.stockDutyarr[index].prtdepoId);
    scwin.resultShrs = scwin.stockDutyarr[index].stkoptDutyTotGrntShrs;
    if (scwin.nowDate > scwin.dateFormat(scwin.stockDutyarr[index].prtdepoEndDd)) {
        $c.util.getComponent('addRow').setStyle("display", "none");
        $c.util.getComponent('register').setStyle("display", "none");
        await $c.win.alert("의무보유기간이 만료 되었습니다.");
    } else {
        $c.util.getComponent('addRow').setStyle("display", "");
        $c.util.getComponent('register').setStyle("display", "");
    }
};

/**
 * @method
 * @name dateFormat
 * @description date Format 처리
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.dateFormat = function (e) {
    const date = e.substring(0, 4) + "-" + e.substring(4, 6) + "-" + e.substring(6, 8);
    return date;
};

/**
 * @method
 * @name deleteRow
 * @description delete Row 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.deleteRow = function (obj) {
    const table = obj.parentNode.parentNode.parentNode.parentNode;
    table.deleteRow(obj.parentNode.parentNode.rowIndex);
    if ($("#stockExerTbody > tr").length === 0) {
        $("#stockExerTbody").append('<tr><td colspan="4" class="td_board_2" >조회내용이 없습니다.</td></tr>');
    }
};

/**
 * @method
 * @name addRow
 * @description add Row 처리
 * @returns {void}
 * @hidden N
 */
scwin.addRow = function () { const d = $c.util.getComponent('dlt_stockDutyList'); if (d && d.insertRow) { d.insertRow(); } };

